import{_ as e,o as t,c as l,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"默里·莱特","description":"","frontmatter":{"title":"默里·莱特","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/默里·莱特.md","filePath":"04_people/默里·莱特.md"}'),i={name:"04_people/默里·莱特.md"};function o(s,a,n,h,_,c){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="默里·莱特" tabindex="-1">默里·莱特 <a class="header-anchor" href="#默里·莱特" aria-label="Permalink to &quot;默里·莱特&quot;">​</a></h1><ul><li><strong>角色职位</strong>：水牛城新闻（Buffalo News）主编</li><li><strong>与巴菲特关系</strong>：Stan利普西时代的编辑，与巴菲特共同守护水牛城新闻内容质量的新闻人</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>默里·莱特是水牛城新闻（The Buffalo News）历史上重要的新闻工作者，与传奇总编斯坦·利普西（Stan Lipsey）时代有着密切的工作关系。在利普西担任水牛城新闻出版人期间，莱特作为编辑骨干，负责报纸的内容编辑工作，是利普西最信赖的搭档之一。</p><p>水牛城新闻是伯克希尔·哈撒韦旗下历史最悠久的媒体资产之一。巴菲特对这份报纸有着深厚的个人情感，他于1977年收购了该报，并在后来多次表达对这份报纸的珍视。在巴菲特和利普西的领导下，默里·莱特作为编辑，确保了水牛城新闻在内容质量和新闻专业性上保持高标准。</p><p>默里·莱特的工作体现了水牛城新闻长期坚持的新闻理念——为读者提供准确、深入、有价值的本地新闻和评论。在报纸行业面临数字化冲击的背景下，水牛城新闻凭借其高质量的内容和忠实的读者群体，在伯克希尔的媒体资产组合中保持了相对稳定的经营表现。莱特作为编辑，为这一成绩的取得做出了重要贡献。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1970-1980年代</strong>：在水牛城新闻担任编辑，与利普西共同塑造报纸风格</li><li><strong>1980-1990年代</strong>：继续担任编辑职务，守护水牛城新闻的内容质量</li><li><strong>Stan利普西时代结束后</strong>：作为利普西时代的老员工，为报纸平稳过渡提供支持</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=默里·莱特在2012年股东信中的原话">2012年：完整翻译|/01_letters/2012年/翻译</a></li><li><a href="/search.html?q=默里·莱特在1986年股东信中的原话">1986年：完整翻译|/01_letters/1986年/翻译</a></li><li><a href="/search.html?q=默里·莱特在1990年股东信中的原话">1990年：完整翻译|/01_letters/1990年/翻译</a></li><li><a href="/search.html?q=默里·莱特在1991年股东信中的原话">1991年：完整翻译|/01_letters/1991年/翻译</a></li><li><a href="/search.html?q=默里·莱特在2007年股东信中的原话">2007年：完整翻译|/01_letters/2007年/翻译</a></li></ul>',11)])])}const f=e(i,[["render",o]]);export{d as __pageData,f as default};
